export type EventAggregateResp = {
    /**
     * Items
     */
    items: Array<EventAggregateItem>;
    /**
     * Total
     */
    total: number;
    /**
     * Page Num
     */
    page_num: number;
    /**
     * Page Size
     */
    page_size: number;
};

/**
 * EventListResp
 *
 * 消息中心列表响应：latest 为最新一条，total 为完整分页。
 *
 * `total_count` / `unread_count` 用于**对账**——列表按「来源实体」聚合，单页只返回
 * `page_size` 张卡片（每张卡片聚合了 N 个用户的同类互动），因此本页 `items` 长度
 * 天然小于「未读事件数」。这两个字段给出真实总量，避免前端把「单页 20 张」误判为
 * 「全部只有 20 条 / 已结束」：
 * - `total_count`：当前筛选条件下聚合卡片（分组）总数，决定总页数；
 * - `unread_count`：当前 `event_type` 下未读事件总数，与 `GET /unread` 的对应字段一致。
 */
export type EventListResp = {
    latest: EventMsgfeedSection;
    total: EventMsgfeedSection;
    /**
     * Total Count
     *
     * 当前筛选条件下聚合卡片（分组）总数（与单页 items 长度无关）
     */
    total_count?: number;
    /**
     * Unread Count
     *
     * 当前 event_type 下未读事件总数，对齐 GET /unread 的对应字段
     */
    unread_count?: number;
};

/**
 * EventMsgfeedContent
 *
 * 聚合条目中的内容实体（对齐 B 站 msgfeed 的 item）。
 *
 * 评论层级关系（root_id / source_id / target_id）与正文（source_content /
 * target_content）、作者（source_mid / target_mid）读取时按 source_id（rpid）
 * 实时回捞评论补全（见 Phase L2 / §5.12），不冗余存储，仅靠
 * resource_id + resource_type 唯一定位原资源；正文与作者统一经
 * `CommentBiz.batch_get_resources` 批量回捞（对齐 §5.11 的 Biz 体系）。
 *
 * `title` / `desc` / `image` 同样读取时按 source_type + source_id 实时回捞
 * 原资源补全，不冗余存储快照。
 *
 * **跳转 uri 不在此拼接**：`business`（source_type）+ `type`（event_type）已足够
 * 定位业务，uri 由前端按这两个字段自行决定。`business_name` 是 `business` 的
 * 文字形式（computed field），供前端直接展示「对动态 / 对评论」的提醒。
 */
export type EventMsgfeedContent = {
    /**
     * Item Id
     */
    item_id: number;
    /**
     * Type
     */
    type: number;
    /**
     * Business
     */
    business?: number;
    /**
     * Resource Type
     */
    resource_type?: number;
    /**
     * Resource Id
     */
    resource_id?: string;
    /**
     * Root Id
     */
    root_id?: string;
    /**
     * Source Id
     */
    source_id?: string;
    /**
     * Target Id
     */
    target_id?: string;
    /**
     * Title
     */
    title?: string;
    /**
     * Desc
     */
    desc?: string;
    /**
     * Image
     */
    image?: string;
    /**
     * Source Content
     */
    source_content?: string;
    /**
     * Target Content
     */
    target_content?: string;
    /**
     * Source Mid
     */
    source_mid?: number;
    /**
     * Target Mid
     */
    target_mid?: number;
    /**
     * Source Name
     */
    source_name?: string;
    /**
     * Target Name
     */
    target_name?: string;
    /**
     * Comment Deleted
     */
    comment_deleted?: boolean;
    /**
     * Jump Target
     */
    jump_target?: string;
    /**
     * Resource Deleted
     */
    resource_deleted?: boolean;
    /**
     * Ctime
     */
    ctime: number;
    /**
     * Business Name
     *
     * `business`（source_type）的文字名称，如「动态」/「评论」/「抽奖」。
     *
     * 前端据此直接展示这是对哪种实体的提醒，无需自行维护 business→文案 的映射。
     * 未知 / 缺省 business 统一回落「其他」。
     */
    readonly business_name: string;
    /**
     * Item Idstr
     */
    readonly item_idStr: string | null;
    /**
     * Source Midstr
     */
    readonly source_midStr: string | null;
    /**
     * Target Midstr
     */
    readonly target_midStr: string | null;
};

