/**
 * InteractionResource
 *
 * 互动目标资源的**统一表示**（2.47.0；非 DB 表）。
 *
 * 各互动操作子类的 ``get_resource()`` 统一返回本模型，把具体资源
 * （`TMoment` / RPC 详情等）折叠成统一字段，供基类统一做
 * 存在性（``exists``）/ 可互动性（``interactable``）/ 作者关系
 * （``author_mid``，关注 / 黑名单校验）判断，以及 ``after_execute`` hook
 * 取作者 / 内容。
 */
export type InteractionResource = {
    /**
     * 资源类型
     */
    bizType: InteractionBizTypeEnum;
    /**
     * Bizid
     *
     * 资源 id（动态时 = dynId）
     */
    bizId: number;
    /**
     * Authormid
     *
     * 资源作者 mid（未知/非动态资源可为空）
     */
    authorMid?: number | null;
    /**
     * Ownermid
     *
     * 资源所有者 mid（DAC `OWNER_ONLY` 校验依据；未知时经 RPC/子类覆盖判断）
     */
    ownerMid?: number | null;
    /**
     * Exists
     *
     * 资源是否存在
     */
    exists?: boolean;
    /**
     * Interactable
     *
     * 是否可互动（如动态需 normal 未软删；收藏语义允许 auditing）
     */
    interactable?: boolean;
    /**
     * Title
     *
     * 附加展示字段（可选，通知等使用）
     */
    title?: string | null;
    /**
     * Content
     *
     * 内容摘要（可选，通知等使用）
     */
    content?: string | null;
    /**
     * Cover
     *
     * 封面图（动态首图 / 资源卡封面，可选）
     */
    cover?: string | null;
    /**
     * Jumptarget
     *
     * 后端下发的跳转目标 route:{name}?{query}（事件提醒等读取侧随资源返回；见计划书 §2.10 / §5.11）
     */
    jumpTarget?: string | null;
};

/**
 * InteractionStatusItem
 *
 * 某资源当前用户交互态（收藏 + 点赞 + 点踩 + 计数）。
 *
 * 2.62.0（计划书 §5.20）：新增 ``isDislike``，供动态卡片渲染点踩态（匿名观众 ``mid=0`` 恒 false）。
 * **点踩计数不外露**：``dislikeCount`` 仍在 ``TInteractionStat`` 内供 EdgeRank 全局降权使用，但不出参。
 */
export type InteractionStatusItem = {
    /**
     * 资源类型（InteractionBizTypeEnum 值）
     */
    bizType: InteractionBizTypeEnum;
    /**
     * Bizid
     *
     * 资源 id（字符串）
     */
    bizId: string;
    /**
     * Islike
     *
     * 当前用户是否已赞
     */
    isLike?: boolean;
    /**
     * Isfavorite
     *
     * 当前用户是否已收藏
     */
    isFavorite?: boolean;
    /**
     * Isdislike
     *
     * 当前用户是否已点踩（2.62.0；匿名恒 false）
     */
    isDislike?: boolean;
    /**
     * Likecount
     *
     * 点赞数
     */
    likeCount?: number;
    /**
     * Favoritecount
     *
     * 收藏数
     */
    favoriteCount?: number;
    /**
     * Commentcount
     *
     * 评论数（dynamic 时=动态统计；非动态资源无评论，恒为 0）
     */
    commentCount?: number;
    /**
     * Repostcount
     *
     * 转发数（dynamic 时=动态统计；非动态资源无转发，恒为 0）
     */
    repostCount?: number;
    /**
     * Viewcount
     *
     * 浏览数（dynamic 与非动态统一=TInteractionStat.viewCount）
     */
    viewCount?: number;
    /**
     * Reportcount
     *
     * 被举报次数（累计，COUNT(*)，2.40.0）
     */
    reportCount?: number;
    /**
     * Reportpeoplecount
     *
     * 举报人数（去重举报人，COUNT(DISTINCT reportMid)，2.40.0）
     */
    reportPeopleCount?: number;
    /**
     * 资源详情（非动态资源经 RPC 获取，弱依赖可空；2.18.0）
     */
    detail?: ResourceDetail | null;
};

