/**
 * SystemNotifyItem
 *
 * 模仿 B 站 `/x/v2/feedsystem/system_notify/get` 的列表项。
 *
 * - `cursor`：发布时间（UTC）的纳秒时间戳，与 B 站一致。
 * - `content`：B 站把正文包成 `{"web": "..."}` 的 JSON 字符串。
 * - `type`：系统通知固定为 4。
 * - `is_send`：映射本服务的 `dispatched`（是否已投递推送）。
 */
export type SystemNotifyItem = {
    /**
     * Id
     */
    id: number;
    /**
     * Cursor
     */
    cursor?: number;
    /**
     * Type
     */
    type?: number;
    /**
     * Title
     */
    title: string;
    /**
     * Content
     */
    content: string;
    source?: SystemNotifySource;
    /**
     * Time At
     */
    time_at?: string;
    /**
     * Card Type
     */
    card_type?: number;
    /**
     * Card Brief
     */
    card_brief?: string;
    /**
     * Card Msg Brief
     */
    card_msg_brief?: string;
    /**
     * Card Cover
     */
    card_cover?: string;
    /**
     * Card Story Title
     */
    card_story_title?: string;
    /**
     * Card Link
     */
    card_link?: string;
    /**
     * Mc
     */
    mc?: string;
    /**
     * Is Station
     */
    is_station?: number;
    /**
     * Is Send
     */
    is_send?: number;
    /**
     * Notify Cursor
     */
    notify_cursor?: number;
};

